let options = [];
let adminSelfOption;
let currentAdminOwner;

options = users.docs.filter(d => normalizeDashboardRole(d.data().role) === 'pm').map(d => ({email:d.id,name:d.data().displayName || d.id}));
const self = users.docs.find(d => getEmailKey({email:d.id}) === email && d.data().role === 'admin');
if (self) adminSelfOption = {email, name:self.data().displayName || email};
currentAdminOwner = users.docs.find(d => getEmailKey({email:d.id}) === draft.assignment.ownerEmail && d.data().role === 'admin');

options.forEach(user => select.add(new Option(`${user.name} (${user.email})`,user.email)));
if (key === 'ownerEmail' && adminSelfOption && !options.some(user => user.email === email)) select.add(new Option(`${adminSelfOption.name} (${email})`,email));
if (key === 'ownerEmail' && currentAdminOwner && draft.assignment.ownerEmail !== email) {
  const current = new Option(`${draft.project.owner || draft.assignment.ownerEmail} (current assignment)`,draft.assignment.ownerEmail);
  current.disabled = true; select.add(current);
}
